/**
 * Shared Mapping Strategy Field Component
 *
 * Author: Mike Nimer <mikenimer@google.com>
 *
 * Purpose:
 * Renders a reusable mapping/serialization strategy selector for Apache Beam connectors
 * where code is dynamically generated by Gemini. Supports:
 * - 'none': Omit the optional translation/mapper call (pass-through).
 * - 'infer': Let Gemini automatically synthesize the inline RowMapper / POJO / SimpleFunction.
 * - 'schema': Define explicit fields & types via the shared 3-tab SchemaEditor (like BigQueryIO).
 * - 'customClass': Escape hatch for referencing a pre-compiled Java class on the classpath.
 */

import React from 'react';
import { InfoTooltip } from '../InfoTooltip';
import { PropertyField } from './PropertyField';
import { SchemaEditor, BEAM_SCHEMA_TYPES, type SchemaField } from './SchemaEditor';

export type MappingStrategy = 'none' | 'infer' | 'schema' | 'customClass';

export interface MappingStrategyFieldProps {
  id: string;
  strategyName?: string;
  strategy: MappingStrategy | string;
  options?: readonly MappingStrategy[];
  optionLabels?: Partial<Record<MappingStrategy, string>>;
  label: string;
  tooltip: string;
  noneDescription?: React.ReactNode;
  inferDescription: React.ReactNode;
  schemaFields: SchemaField[];
  schemaTypes?: readonly string[];
  schemaTitle?: string;
  schemaStringTitle?: string;
  schemaStringPlaceholder?: string;
  onSchemaChange: (data: {
    schemaFields: SchemaField[];
    schema: string;
    schemaString: string;
  }) => void;
  customClassId?: string;
  customClassName?: string;
  customClassLabel?: string;
  customClassTooltip?: string;
  customClassPlaceholder?: string;
  customClassValue?: string;
  customClassChildren?: React.ReactNode;
  onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => void;
}

const DEFAULT_OPTIONS: readonly MappingStrategy[] = ['infer', 'schema', 'customClass'];

const DEFAULT_OPTION_LABELS: Record<MappingStrategy, string> = {
  none: 'None — Pass Through Unchanged (Default)',
  infer: 'Auto-Infer from Query / Table (Recommended)',
  schema: 'Define Schema (Fields & Types)',
  customClass: 'Custom Class Name (Optional)'
};

export const MappingStrategyField: React.FC<MappingStrategyFieldProps> = ({
  id,
  strategyName = 'mapperStrategy',
  strategy,
  options = DEFAULT_OPTIONS,
  optionLabels,
  label,
  tooltip,
  noneDescription,
  inferDescription,
  schemaFields,
  schemaTypes = BEAM_SCHEMA_TYPES,
  schemaTitle = 'Beam Schema Specification',
  schemaStringTitle = 'Beam Schema String',
  schemaStringPlaceholder = 'e.g. id:STRING:REQUIRED, name:STRING, metric_val:DOUBLE, recorded_at:TIMESTAMP',
  onSchemaChange,
  customClassId,
  customClassName,
  customClassLabel,
  customClassTooltip,
  customClassPlaceholder,
  customClassValue,
  customClassChildren,
  onChange
}) => {
  const labels = { ...DEFAULT_OPTION_LABELS, ...optionLabels };

  return (
    <div className="flex flex-col gap-2.5">
      <div className="flex flex-col gap-1">
        <label htmlFor={id} className="flex items-center text-xs font-bold uppercase text-slate-500">
          <span>{label}</span>
          <InfoTooltip text={tooltip} />
        </label>
        <select
          id={id}
          name={strategyName}
          value={strategy}
          onChange={onChange}
          aria-label={label}
          className="w-full px-2 py-1.5 rounded bg-[var(--vscode-input-background)] text-[var(--vscode-input-foreground)] border border-[var(--vscode-input-border)] focus:outline-none focus:border-[var(--vscode-focusBorder)] text-xs"
        >
          {options.map(opt => (
            <option key={opt} value={opt}>
              {labels[opt]}
            </option>
          ))}
        </select>
      </div>

      {strategy === 'none' && (
        <div className="p-2.5 rounded bg-slate-800/50 border border-slate-700/60 text-xs text-slate-300">
          {noneDescription || (
            <>
              <span className="font-semibold text-slate-200">Pass-Through Mode:</span> No translation function will be emitted; raw elements pass through unchanged.
            </>
          )}
        </div>
      )}

      {strategy === 'infer' && (
        <div className="p-2.5 rounded bg-blue-500/10 border border-blue-500/30 text-xs text-blue-300">
          <span className="font-semibold">Dynamic Inference:</span> {inferDescription}
        </div>
      )}

      {strategy === 'schema' && (
        <div className="p-3 bg-slate-800/40 rounded border border-purple-500/30 flex flex-col gap-2.5">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1.5">
              <span className="text-xs font-bold uppercase text-slate-300">Table / Element Schema</span>
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-purple-500/20 text-purple-300 font-mono font-semibold">
                {schemaFields.length} {schemaFields.length === 1 ? 'FIELD' : 'FIELDS'}
              </span>
            </div>
            <InfoTooltip text="Define schema columns and types. Gemini will synthesize the Beam Schema, inline mapper, or POJO matching these fields." />
          </div>
          <SchemaEditor
            fields={schemaFields}
            types={schemaTypes}
            schemaTitle={schemaTitle}
            stringTitle={schemaStringTitle}
            stringPlaceholder={schemaStringPlaceholder}
            jsonTextareaId={`${id}SchemaJson`}
            stringTextareaId={`${id}SchemaString`}
            onChange={onSchemaChange}
          />
        </div>
      )}

      {strategy === 'customClass' && (
        <div className="flex flex-col gap-2 mt-0.5 pl-2 border-l-2 border-[var(--vscode-highlight)]/50">
          {customClassChildren || (
            <PropertyField
              id={customClassId}
            name={customClassName}
            label={customClassLabel}
            tooltip={customClassTooltip}
            value={customClassValue}
            onChange={onChange}
            placeholder={customClassPlaceholder}
              mono={true}
            />
          )}
        </div>
      )}
    </div>
  );
};
